const fs=require('fs'),p=require('path'),c=require('crypto');
const need=(v,m)=>{if(!v)throw Error(m)},fields=['dev','ino','mode','size','mtimeNs','ctimeNs','nlink'];
function readExact(i){const x=i.path;need(p.isAbsolute(x)&&p.normalize(x)===x,'absolute normalized');let a='/';for(const k of x.split('/').filter(Boolean)){a=p.join(a,k);need(!fs.lstatSync(a).isSymbolicLink(),'symlink');}const s=fs.lstatSync(x,{bigint:true});need(s.isFile()&&s.size<=67108864n,'regular cap');if(i.bytes!==undefined)need(s.size===BigInt(i.bytes),'initial size');const same=t=>fields.every(k=>t[k]===s[k]);const fd=fs.openSync(x,fs.constants.O_RDONLY|fs.constants.O_NOFOLLOW);let b;try{need(same(fs.fstatSync(fd,{bigint:true})),'fd-before');const chunks=[];let n=0,cap=Number(s.size)+1;while(n<cap){const z=Buffer.alloc(Math.min(65536,cap-n)),g=fs.readSync(fd,z,0,z.length,null);if(!g)break;chunks.push(z.subarray(0,g));n+=g;}b=Buffer.concat(chunks);need(b.length===Number(s.size)&&same(fs.fstatSync(fd,{bigint:true})),'fd-after/length');}finally{fs.closeSync(fd);}need(same(fs.lstatSync(x,{bigint:true}))&&fs.realpathSync(x)===x,'path-after');const r={path:x,bytes:b.length,sha256:c.createHash('sha256').update(b).digest('hex')};if(i.sha256!==undefined)need(r.sha256===i.sha256,'hash');return {...r,body:b};}
const simple=r=>({path:r.path,bytes:r.bytes,sha256:r.sha256});

const mode=process.argv[1]||'preseal';
need(['preseal','final6'].includes(mode),'mode');
const dir="/Volumes/AI_DATA/development/det-review-evidence/ri250-native-canonical-literals-7_4sso63";
const names4=['BINDING_GAP.md','MANUAL_CONSEQUENCE.md','HANDOFF.md','SOURCE_REFERENCES.json'].sort();
const names6=[...names4,'AUTHOR_VERIFICATION.json','HANDOFF.json'].sort();
const expected=mode==='preseal'?names4:names6;
const canon=x=>Array.isArray(x)?x.map(canon):(x&&typeof x==='object'?Object.fromEntries(Object.keys(x).sort().map(k=>[k,canon(x[k])])):x);
const eq=(a,b)=>JSON.stringify(canon(a))===JSON.stringify(canon(b));
const same=(a,b)=>['path','bytes','sha256'].every(k=>a[k]===b[k]);
need(fs.lstatSync(dir).isDirectory()&&!fs.lstatSync(dir).isSymbolicLink(),'reservation');
need(eq(fs.readdirSync(dir).sort(),expected),'namespace');
const reads=new Map();
function pinned(i){
 need(!i.path.endsWith('/CERTIFICATE.json')&&!i.path.endsWith('/check.py'),'no original body or executor');
 const r=readExact(i),old=reads.get(r.path);
 if(old)need(same(old,r),'repeated identity');
 reads.set(r.path,simple(r));return r;
}
const current=names4.map(n=>pinned({path:p.join(dir,n)}));
const S=JSON.parse(current.find(r=>p.basename(r.path)==='SOURCE_REFERENCES.json').body.toString('utf8'));
need(S.schema==='ri250-admitted-source-references-v1'&&S.status==='SOURCE_ONLY_AUTHOR_GAP_PACKET_FOR_INDEPENDENT_REVIEW','source schema/status');
const ass=JSON.parse(pinned(S.assignment).body.toString('utf8'));
need(ass.schema==='ri250-canonical-two-role-assignment-v1'&&ass.status==='ASSIGNED_AFTER_PREDECESSOR_ADJUDICATION','assignment');
need(ass.reservation===dir&&ass.thread==='01a074c4-4b09-76a3-8cb2-0caf116f6b9c','owner');
need(same(ass.assignment,S.assignment_text)&&same(ass.admission,S.literal_admission)&&same(ass.predecessor,S.accepted_predecessor),'authority links');
pinned(S.assignment_text);
const dec=JSON.parse(pinned(S.accepted_predecessor).body.toString('utf8'));
need(dec.status==='ACCEPT_COMPLETE_COMPANION_WEIGHTED_EXCHANGE_DUAL_NECESSITY_AND_STRUCTURAL_KEYS_ONLY','adjudication');
const adm=JSON.parse(pinned(S.literal_admission).body.toString('utf8'));
need(adm.schema==='ri250-bounded-original-canonical-literal-admission-v1'&&adm.status==='AUTHORIZE_BOUNDED_MANUAL_LITERAL_BINDING_ONLY','literal admission');
need(adm.other_literal_exceptions_closed===true&&adm.scientific_execution===false,'admission boundaries');
const P=JSON.parse(pinned(S.predecessor_references).body.toString('utf8'));
need(S.preserved_boundary_keys.length===15&&eq(S.preserved_boundary_keys,P.preserved_boundary_keys),'boundary keys');
for(const k of S.preserved_boundary_keys)need(eq(S.preserved_boundaries[k],P.preserved_boundaries[k]),'boundary '+k);
const paths=S.direct_sources.map(r=>r.identity.path);
need(paths.length===113&&new Set(paths).size===paths.length,'direct count/unique');
for(const row of S.direct_sources){
 need(['accepted-analytic-text','administrative-reference','opaque-historical-support'].includes(row.access),'access class');
 pinned(row.identity);
}
for(const row of P.direct_sources)need(S.direct_sources.some(x=>same(x.identity,row.identity)),'inherited direct source');
const prev=JSON.parse(pinned(S.predecessor_handoff).body.toString('utf8'));
need(prev.schema==='ri248-native-canonical-companion-handoff-v1','predecessor schema');
for(const i of prev.files)pinned(i);
const prevNames=fs.readdirSync(p.dirname(S.predecessor_handoff.path)).sort();
need(eq(prevNames,['AUTHOR_VERIFICATION.json','CANONICAL_BINDING.md','COMPANION_ROW.md','HANDOFF.json','HANDOFF.md','SOURCE_REFERENCES.json'].sort()),'predecessor exact namespace');
const lit=S.current_literal_exception;
need(same(lit.admission,S.literal_admission)&&same(lit.original_identity,adm.expected_original),'separate literal identity');
need(!paths.includes(lit.original_identity.path),'original not in direct sources');
need(lit.permitted_display_count===1&&lit.actual_display_count===1&&lit.untruncated===true&&lit.whole_custody_before_after===true,'literal declaration');
need(lit.receipt.chunk_id==='ffd6a7'&&lit.receipt.exit_code===0&&lit.receipt.complete_display===true,'actual literal receipt reference');
need(lit.original_index_binding===false&&lit.sparse_absence_zero_rule_bound===false&&lit.canonical_role_strings_transcribed.length===0,'binding stop');
need(lit.final_status==='STOPPED_GAP_INDEX_WITH_ADDITIONAL_GAP_SCHEMA'&&lit.extra_coefficients_used===false&&lit.scientific_JSON_decoded===false&&lit.scientific_arithmetic===false&&lit.body_copy_written===false,'literal limits');
need(S.closed_prior_literal_exceptions_by_reference.all_older_exceptions_remain_closed===true,'old closed');
need(S.current_scope.scientific_body_literal_display===true&&S.current_scope.scientific_body_opaque_hash===true,'current admitted display recorded');
for(const k of ['automatic_scientific_arithmetic','scientific_JSON_decoded','new_coordinate_read','role_values_acquired','incidental_values_used','full_vector_instantiated','H_or_z_reconstructed','new_amplitude','subject_execution','measurement_access','RET_access','repository_changes','git_or_index_operations','source_admission_issued','successor_assigned','old_literal_exceptions_renewed'])need(S.current_scope[k]===false,'current scope '+k);
need(S.current_scope.qualification_credit===0,'credit');
for(const k of ['failed_shell_commands','failed_orchestration_attempts','rejected_patches','clipped_displays'])need(S.diagnostics[k]===0,'current diagnostics');
need(eq(S.diagnostics.predecessor_diagnostics,P.diagnostics),'inherited diagnostics');
if(mode==='final6'){
 const H=JSON.parse(pinned({path:p.join(dir,'HANDOFF.json')}).body.toString('utf8'));
 need(H.schema==='ri250-native-canonical-literals-handoff-v1'&&H.status==='SEALED_BINDING_GAP_PENDING_INDEPENDENT_REVIEW','handoff');
 need(H.reservation===dir&&H.files.length===5&&eq(H.namespace,names6),'handoff payloads');
 for(const i of H.files)pinned(i);
 const ai=H.files.find(i=>p.basename(i.path)==='AUTHOR_VERIFICATION.json');need(ai,'author pin');
 const A=JSON.parse(pinned(ai).body.toString('utf8'));
 need(A.schema==='ri250-author-verification-v1'&&A.independent_acceptance===false&&A.scientific_execution===false,'author scope');
 need(eq(A.payloads,current.map(simple)),'author four pins');
 need(eq(A.diagnostics,S.diagnostics)&&eq(H.diagnostics,S.diagnostics),'consistent diagnostics');
 for(const i of current.map(simple))need(H.files.some(j=>same(i,j)),'current payload pin');
 need(H.result==='GAP-INDEX_WITH_ADDITIONAL_UNCLOSED_GAP-SCHEMA'&&H.role_values_acquired===false&&H.sufficient_gap_test_performed===false,'gap result');
 for(const k of ['actual_full_normalized_witness','actual_signed_inconsistency','canonical_Cb_resolved','actual_kappa_gap_resolved','successor_assigned'])need(H[k]===false,'result limit '+k);
 for(const k of ['complete_original_recovery_retained','accepted_full_system_iff_retained','inherited_zero_hook_branch_retained'])need(H[k]===true,'retention '+k);
 need(H.qualification_credit===0,'handoff credit');
}
for(const i of reads.values())readExact(i);
console.log(JSON.stringify({
schema:'ri250-metadata-check-result-v1',mode,exit_intent:0,
scope:'Administrative identities, namespaces, unchanged boundaries and declarations only. No original scientific body opened by this check; no proof or value computation.',
direct_sources:S.direct_sources.length,direct_bytes:S.direct_sources.reduce((n,x)=>n+x.identity.bytes,0),whole_identities:reads.size,
preserved_boundaries:S.preserved_boundary_keys.length,
inherited_manifest_sources_by_reference:S.preserved_boundaries.inherited_manifest_by_reference.selected_paths,
separate_literal_receipt:lit.receipt.chunk_id,
separate_literal_identity:lit.original_identity,
original_scientific_body_opened_by_this_check:false,scientific_JSON_decoded:false,scientific_arithmetic:false,
canonical_role_strings_transcribed:0,sufficient_gap_test_performed:false,
current_namespace:expected,predecessor_namespace:prevNames,
current_identities:[...reads.values()].filter(x=>p.dirname(x.path)===dir)
}));
